/**
 * lufs-seed derivation — JavaScript reference port.
 *
 * DERIVE ONLY. Minting stays in the Python CLI (it needs health tests, file
 * I/O and signing). This is the half that has to run in a browser, because
 * amacher-visual-process renders there and must produce the SAME stream from
 * the same seed as the Python side does.
 *
 * That agreement is the entire point of the spec being HMAC-SHA256 and
 * nothing else: this file is ~80 lines and depends only on node:crypto /
 * WebCrypto. Verify it with tests/fixtures/derivation-vectors.json, which is
 * generated by the Python implementation.
 *
 *   import { deriveFloats } from './lufs-seed-derive.mjs';
 *   const v = await deriveFloats(seedHex, 'study-07/palette', 4);
 */

const enc = new TextEncoder();

function hexToBytes(hex) {
  const clean = hex.trim().toLowerCase();
  if (!/^[0-9a-f]*$/.test(clean) || clean.length % 2 !== 0) {
    throw new Error('invalid hex');
  }
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(clean.substr(i * 2, 2), 16);
  }
  return out;
}

function bytesToHex(bytes) {
  return Array.from(bytes).map((b) => b.toString(16).padStart(2, '0')).join('');
}

async function getSubtle() {
  if (typeof globalThis.crypto !== 'undefined' && globalThis.crypto.subtle) {
    return globalThis.crypto.subtle;
  }
  const { webcrypto } = await import('node:crypto');
  return webcrypto.subtle;
}

async function hmacSha256(key, data) {
  const subtle = await getSubtle();
  const cryptoKey = await subtle.importKey(
    'raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'],
  );
  return new Uint8Array(await subtle.sign('HMAC', cryptoKey, data));
}

function concat(...arrays) {
  const total = arrays.reduce((n, a) => n + a.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const a of arrays) { out.set(a, off); off += a.length; }
  return out;
}

/** RFC 5869 section 2.3. */
export async function hkdfExpand(prk, info, length) {
  const HASH_LEN = 32;
  if (length > 255 * HASH_LEN) throw new Error('length too large for one expand');
  const out = new Uint8Array(length);
  let block = new Uint8Array(0);
  let pos = 0;
  let counter = 1;
  while (pos < length) {
    block = await hmacSha256(prk, concat(block, info, new Uint8Array([counter])));
    const take = Math.min(block.length, length - pos);
    out.set(block.subarray(0, take), pos);
    pos += take;
    counter += 1;
  }
  return out;
}

const DERIVE_INFO_PREFIX = enc.encode('lufs-seed/v1/derive');

/** Raw bytes under a label. Mirrors lufs_seed.kdf.derive. */
export async function derive(seedHex, label, length = 32) {
  const seed = hexToBytes(seedHex);
  if (seed.length !== 32) throw new Error('seed must be 32 bytes');
  const info = concat(DERIVE_INFO_PREFIX, enc.encode('/' + label));
  const maxPerChunk = 255 * 32;
  if (length <= maxPerChunk) return hkdfExpand(seed, info, length);

  // Chunk 0 uses the PLAIN info so a long draw stays a strict extension of a
  // short one. Must match lufs_seed/kdf.py exactly — the boundary vectors in
  // tests/fixtures/derivation-vectors.json exist to police this.
  const out = new Uint8Array(length);
  out.set(await hkdfExpand(seed, info, maxPerChunk), 0);
  let pos = maxPerChunk;
  let chunk = 1;
  while (pos < length) {
    const chunkInfo = concat(info, enc.encode('/chunk/' + chunk));
    const take = Math.min(maxPerChunk, length - pos);
    out.set((await hkdfExpand(seed, chunkInfo, take)).subarray(0, take), pos);
    pos += take;
    chunk += 1;
  }
  return out;
}

export async function deriveHex(seedHex, label, length = 32) {
  return bytesToHex(await derive(seedHex, label, length));
}

/** Floats in [0,1). Top 53 bits of each 8-byte word — matches Python. */
export async function deriveFloats(seedHex, label, count) {
  const raw = await derive(seedHex, label, count * 8);
  const out = [];
  for (let i = 0; i < count; i++) {
    // Build the top 53 bits without BigInt loss: high 32 bits and next 21.
    const b = raw.subarray(i * 8, i * 8 + 8);
    const hi = ((b[0] << 24) >>> 0) + (b[1] << 16) + (b[2] << 8) + b[3];
    const lo = ((b[4] << 24) >>> 0) + (b[5] << 16) + (b[6] << 8) + b[7];
    // (hi*2^32 + lo) >> 11  ==  hi * 2^21 + (lo >>> 11)
    const value = hi * 2097152 + (lo >>> 11);
    out.push(value / 9007199254740992); // 2^53
  }
  return out;
}

/** Ints in [low, high] inclusive. Rejection sampling — matches Python. */
export async function deriveInts(seedHex, label, count, low, high) {
  if (high < low) throw new Error('high must be >= low');
  const span = high - low + 1;
  if (span === 1) return new Array(count).fill(low);

  const nbytes = Math.max(1, Math.ceil(Math.log2(span) / 8));
  const limit = Math.pow(256, nbytes);
  const ceiling = limit - (limit % span);

  const out = [];
  let batch = Math.max(count * nbytes * 2, 64);
  let raw = await derive(seedHex, label, batch);
  let pos = 0;
  while (out.length < count) {
    if (pos + nbytes > raw.length) {
      batch *= 2;
      raw = await derive(seedHex, label, batch);
      pos = 0;
      out.length = 0;
      continue;
    }
    let word = 0;
    for (let i = 0; i < nbytes; i++) word = word * 256 + raw[pos + i];
    pos += nbytes;
    if (word < ceiling) out.push(low + (word % span));
  }
  return out;
}

export async function deriveChoice(seedHex, label, items) {
  if (!items.length) throw new Error('empty sequence');
  const [i] = await deriveInts(seedHex, label, 1, 0, items.length - 1);
  return items[i];
}

export async function deriveShuffle(seedHex, label, items) {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const [j] = await deriveInts(seedHex, `${label}/swap/${i}`, 1, 0, i);
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
